def get_horizontal_lines(grid):
    """Cells that are part of horizontal line segments of length >= 2"""
    result = set()
    for r in range(h):
        i = 0
        while i < w:
            if grid[r][i] != 1:
                j = i
                while j < w and grid[r][j] == grid[r][i] and grid[r][j] != 1:
                    j += 1
                if j - i >= 2:
                    for c in range(i, j):
                        result.add((r, c))
                i = j
            else:
                i += 1
    return result

def get_vertical_lines(grid):
    """Cells that are part of vertical line segments of length >= 2"""
